const express = require('express');
const { DataSource } = require('typeorm');

const app = express();
const AppDataSource = new DataSource({
  type: 'postgres',
  url: process.env.DATABASE_URL,
  synchronize: false
});

AppDataSource.initialize();

app.get('/api/contracts/:id', async (req, res) => {
  const { id } = req.params;

  // Enforce tenant scoping inside the raw SQL query
  try {
    const rawResult = await AppDataSource.query(
      `SELECT c.id, c.title, c.contract_value, c.payload_blob, s.signatory_name, s.signed_at
       FROM enterprise_contracts c
       LEFT JOIN signatories s ON c.id = s.contract_id
       WHERE c.id = $1 AND c.tenant_id = $2`,
      [id, req.user.tenantId]
    );

    if (!rawResult || rawResult.length === 0) {
      return res.status(404).json({ error: 'Contract not found' });
    }

    return res.json({ contract: rawResult[0] });
  } catch (err) {
    return res.status(500).json({ error: 'Database query execution failed' });
  }
});

module.exports = app;
